  // Urgency pulse effect (glow)
  const pulse = Math.sin((frame * Math.PI) / 15) * 0.5 + 0.5;

  // Infinite Ticker horizontal scrolling
  // Starts with a slight offset, scrolls infinitely based on tickerSpeed
  const tickerX = 100 - frame * tickerSpeed;

  // Repeat ticker items to cover longest duration (60s) without gaps
  const repeatedTickerItems = Array(15).fill(tickerItems).flat();

  // Periodic glossy sheen reflection sweep (every 5 seconds / 150 frames)
  const sheenPeriod = 150;
  const sheenFrame = frame % sheenPeriod;
  const sheenX = interpolate(sheenFrame, [0, 50], [-600, width + 600], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Ticker layout helper variables to guarantee strict bounding container
  const tickerLeftPosition = width * 0.05 + 180;
  const tickerViewportWidth = width * 0.95 - tickerLeftPosition;

